Click to view **Webhook Payload (Flow Submission)** { "namespace": "ChatApps", "eventType": "inbound_message_received", "payload": { "umid": "health-xyz-789", "subAccountId": "your-subaccount-id", "timestamp": "2026-02-10T14:00:00.000Z", "user": { "msisdn": "+15551234567", "channelUserId": "15551234567" }, "recipient": { "channel": "whatsapp", "channelId": "your-channel-id" }, "type": "Interactive", "content": { "interactive": { "type": "nfmReply", "nfmReply": { "responseJson": "{"appointment_type":"sick_visit","provider_preference":"dr_smith","visit_reason_category":"illness","visit_notes":"Persistent cough and fever for 3 days","patient_first_name":"Emily","patient_last_name":"Chen","date_of_birth":"1992-08-22","patient_email":"emily.chen@example.com","insurance_status":"insured","insurance_provider":"Blue Cross Blue Shield","member_id":"BCBS987654321","appointment_date":"2026-02-12","time_slot":"1000","visit_type":"in_person","contact_preferences":["whatsapp","email"],"flow_token":"<TOKEN>"}" } } } } } Processing the Submission: // Parse the Flow submission const data = JSON.parse(payload.content.interactive.nfmReply.responseJson); // Check if patient exists in EMR system let patientRecord = await findPatient({ firstName: data.patient_first_name, lastName: data.patient_last_name, dateOfBirth: data.date_of_birth }); // Create new patient record if doesn't exist if (!patientRecord) { patientRecord = await createPatient({ firstName: data.patient_first_name, lastName: data.patient_last_name, dateOfBirth: data.date_of_birth, email: data.patient_email, phone: payload.user.msisdn, insuranceStatus: data.insurance_status, insuranceProvider: data.insurance_provider, memberId: data.member_id, contactPreferences: data.contact_preferences || ['whatsapp'], source: 'whatsapp_flow' }); } // Verify insurance eligibility (if applicable) let insuranceVerified = true; let copay = 0; if (data.insurance_status === 'insured' && data.member_id) { const insuranceCheck = await verifyInsurance({ provider: data.insurance_provider, memberId: data.member_id, serviceType: data.appointment_type, patientDOB: data.date_of_birth }); insuranceVerified = insuranceCheck.active; copay = insuranceCheck.copay || 0; if (!insuranceVerified) { await sendMessage(payload.user.msisdn, { type: 'text', content: { text: `Hi ${data.patient_first_name}, we couldn't verify your insurance (${data.insurance_provider} - ${data.member_id}).

Please call our office at (555) 123-4567 to confirm your coverage before your appointment.

You can still keep your ${data.appointment_date} at ${data.time_slot} appointment, but payment may be required at check-in.` } }); } } // Check provider availability const providerId = data.provider_preference !== 'any' ? data.provider_preference : await findAvailableProvider({ appointmentType: data.appointment_type, date: data.appointment_date, timeSlot: data.time_slot, visitType: data.visit_type }); const providerAvailable = await checkProviderAvailability({ providerId: providerId, date: data.appointment_date, timeSlot: data.time_slot }); if (!providerAvailable) { // Offer alternative times const alternativeSlots = await getAvailableSlots({ providerId: providerId, appointmentType: data.appointment_type, preferredDate: data.appointment_date, visitType: data.visit_type, daysAhead: 14 }); await sendMessage(payload.user.msisdn, { type: 'text', content: { text: `Hi ${data.patient_first_name}, unfortunately ${data.time_slot} on ${data.appointment_date} is no longer available.

Alternative times:
${alternativeSlots.slice(0, 5).map(s => `• ${s.date} at ${s.time}`).join('
')}

Would you like one of these times? Reply with the number.` } }); return; } // Create appointment in EMR/scheduling system const appointment = await createAppointment({ patientId: patientRecord.id, providerId: providerId, appointmentType: data.appointment_type, visitReasonCategory: data.visit_reason_category, visitNotes: data.visit_notes, scheduledDate: data.appointment_date, scheduledTime: data.time_slot, visitType: data.visit_type, // in_person or telehealth insuranceVerified: insuranceVerified, estimatedCopay: copay, contactPreferences: data.contact_preferences, source: 'whatsapp_flow', status: 'confirmed' }); // Get provider details const provider = await getProviderDetails(providerId); // Send confirmation message const appointmentTime = formatTime(data.time_slot); // "10:00 AM" let confirmationMsg = `✅ Appointment Confirmed!

`; confirmationMsg += `Patient: ${data.patient_first_name} ${data.patient_last_name}
`; confirmationMsg += `Date: ${data.appointment_date}
`; confirmationMsg += `Time: ${appointmentTime}
`; confirmationMsg += `Provider: ${provider.name}
`; confirmationMsg += `Type: ${data.visit_type === 'in_person' ? 'In-Person Visit' : 'Telehealth (Video)'}
`; confirmationMsg += `
Appointment #${appointment.id}

`; if (data.visit_type === 'in_person') { confirmationMsg += `📍 Location:
HealthCare Clinic
123 Medical Center Dr
San Jose, CA 95110

`; confirmationMsg += `Please arrive 15 minutes early to complete check-in.`; } else { confirmationMsg += `💻 You'll receive a video call link 1 hour before your appointment.`; } if (insuranceVerified && copay > 0) { confirmationMsg += `

Estimated copay: $${copay}`; } confirmationMsg += `

Need to reschedule or cancel? Reply to this message.`; await sendMessage(payload.user.msisdn, { type: 'text', content: { text: confirmationMsg } }); // Schedule automated reminders await scheduleReminders({ appointmentId: appointment.id, patientPhone: payload.user.msisdn, patientEmail: data.patient_email, appointmentDate: data.appointment_date, appointmentTime: data.time_slot, contactPreferences: data.contact_preferences || ['whatsapp'], visitType: data.visit_type, reminders: [ { timing: '24_hours_before', channels: ['whatsapp', 'email'] }, { timing: '2_hours_before', channels: ['whatsapp'] } ] }); // Send intake forms if first visit if (!patientRecord.hasCompletedIntake) { await sendMessage(payload.user.msisdn, { type: 'text', content: { text: `📋 One more step! Please complete your medical history forms before your visit:

${process.env.INTAKE_FORM_URL}?patient=${patientRecord.id}

This will save time at check-in.` } }); } // Log for analytics await logAppointmentBooking({ appointmentType: data.appointment_type, visitType: data.visit_type, providerId: providerId, insuranceStatus: data.insurance_status, source: 'whatsapp_flow', leadTime: calculateLeadTime(data.appointment_date), // days in advance newPatient: !patientRecord.hasCompletedIntake, createdAt: new Date() }); Best Practices: HIPAA Compliance: Ensure all patient data is encrypted in transit and at rest Insurance Verification: Validate coverage in real-time to prevent billing issues Smart Scheduling: Check provider availability before confirming appointments Patient Identification: Match patients by name + DOB to avoid duplicate records Intake Forms: Send pre-visit forms for new patients to streamline check-in Automated Reminders: Send 24-hour and 2-hour reminders to reduce no-shows Telehealth Setup: Send video link 1 hour before telehealth appointments with tech check instructions Cancellation Policy: Clearly communicate 24-hour cancellation requirement Follow-up: Send post-visit satisfaction survey and care instructions Analytics: Track no-show rates, appointment types, and booking lead times

Click to view **Webhook Payload (Flow Submission)** { "namespace": "ChatApps", "eventType": "inbound_message_received", "payload": { "umid": "service-abc-123", "subAccountId": "your-subaccount-id", "timestamp": "2026-02-10T10:30:00.000Z", "user": { "msisdn": "+15551234567", "channelUserId": "15551234567" }, "recipient": { "channel": "whatsapp", "channelId": "your-channel-id" }, "type": "Interactive", "content": { "interactive": { "type": "nfmReply", "nfmReply": { "responseJson": "{"service_type":"plumbing","urgency":"emergency","street_address":"456 Oak Avenue","apt_unit":"2A","city":"San Jose","postal_code":"95110","property_type":"apartment","problem_description":"Kitchen sink pipe burst, water leaking heavily","problem_photo":"base64_encoded_photo_data","access_requirements":["building_code","contact_first"],"preferred_date":"2026-02-10","time_slot":"morning","contact_name":"Maria Garcia","contact_phone":"+15559876543","contact_email":"maria@example.com","flow_token":"<TOKEN>"}" } } } } } Processing the Submission: // Parse the Flow submission const data = JSON.parse(payload.content.interactive.nfmReply.responseJson); // Upload problem photo to storage let problemPhotoUrl = null; if (data.problem_photo) { problemPhotoUrl = await uploadToStorage(data.problem_photo, { folder: 'service-requests', filename: `${payload.umid}_problem.jpg` }); } // Determine service urgency and SLA const slaTimes = { emergency: 4, // hours urgent: 48, // hours standard: 120 // hours (5 days) }; const slaHours = slaTimes[data.urgency] || 120; // Check technician availability for requested service type const availableTechs = await findAvailableTechnicians({ serviceType: data.service_type, postalCode: data.postal_code, preferredDate: data.preferred_date, timeSlot: data.time_slot, urgency: data.urgency }); if (!availableTechs || availableTechs.length === 0) { // No availability - offer alternative times const alternativeTimes = await getAlternativeTimeSlots({ serviceType: data.service_type, postalCode: data.postal_code, urgency: data.urgency }); await sendMessage(payload.user.msisdn, { type: 'text', content: { text: `Thank you, ${data.contact_name}! Unfortunately we don't have availability for ${data.time_slot} on ${data.preferred_date}.

Alternative times available:
${alternativeTimes.map(t => `• ${t.date} ${t.slot}`).join('
')}

Our team will call you within 1 hour to schedule the best time.` } }); // Queue for manual scheduling await queueForManualScheduling({ requestData: data, photoUrl: problemPhotoUrl, customerPhone: payload.user.msisdn, alternativeTimes: alternativeTimes }); return; } // Assign best-match technician (skill-based routing) const assignedTech = await assignTechnician({ technicians: availableTechs, serviceType: data.service_type, problemDescription: data.problem_description, urgency: data.urgency }); // Create service appointment in scheduling system const appointment = await createServiceAppointment({ customerId: payload.user.msisdn, technicianId: assignedTech.id, serviceType: data.service_type, urgency: data.urgency, propertyAddress: { street: data.street_address, aptUnit: data.apt_unit, city: data.city, postalCode: data.postal_code, type: data.property_type }, problemDescription: data.problem_description, problemPhotoUrl: problemPhotoUrl, accessRequirements: data.access_requirements || [], scheduledDate: data.preferred_date, timeSlot: data.time_slot, contactInfo: { name: data.contact_name, phone: data.contact_phone, email: data.contact_email }, slaDeadline: new Date(Date.now() + slaHours * 60 * 60 * 1000), source: 'whatsapp_flow' }); // Send confirmation to customer const confirmationMessage = `✅ Appointment Confirmed!

Service: ${data.service_type.toUpperCase()}
Date: ${data.preferred_date}
Time: ${data.time_slot}
Technician: ${assignedTech.name}

Address: ${data.street_address}${data.apt_unit ? ' ' + data.apt_unit : ''}, ${data.city}

Appointment #${appointment.id}

${assignedTech.name} will arrive during your ${data.time_slot} window. You'll receive a notification 30 minutes before arrival.

Questions? Reply here anytime.`; await sendMessage(payload.user.msisdn, { type: 'text', content: { text: confirmationMessage } }); // Send appointment details to technician await notifyTechnician(assignedTech.id, { appointmentId: appointment.id, serviceType: data.service_type, urgency: data.urgency, address: `${data.street_address}${data.apt_unit ? ' ' + data.apt_unit : ''}, ${data.city}`, problemDescription: data.problem_description, problemPhoto: problemPhotoUrl, accessNotes: data.access_requirements, customerContact: data.contact_phone, scheduledTime: `${data.preferred_date} ${data.time_slot}` }); // Log for analytics await logServiceRequest({ serviceType: data.service_type, urgency: data.urgency, propertyType: data.property_type, postalCode: data.postal_code, source: 'whatsapp_flow', assignedTechId: assignedTech.id, createdAt: new Date() }); Best Practices: Skill-Based Routing: Match technicians to service type (plumber, electrician, HVAC specialist) Geographic Optimization: Route to nearest available technician to reduce travel time Photo Upload: Request problem photos to help technicians prepare proper tools/parts Access Requirements: Collect building codes, parking info, pet warnings upfront SLA Tracking: Set and monitor response time commitments based on urgency Proactive Updates: Send "technician on the way" notifications 30 mins before arrival First-Time Fix Rate: Use problem descriptions and photos to bring right parts Follow-up: Send satisfaction survey 24 hours after service completion

Click to view **Webhook Payload (Flow Submission)** { "namespace": "ChatApps", "eventType": "inbound_message_received", "payload": { "umid": "abc-123-def-456", "subAccountId": "your-subaccount-id", "timestamp": "2026-01-20T14:30:00.000Z", "user": { "msisdn": "+15551234567", "channelUserId": "15551234567" }, "recipient": { "channel": "whatsapp", "channelId": "your-channel-id" }, "type": "Interactive", "content": { "interactive": { "type": "nfmReply", "nfmReply": { "responseJson": "{"order_number":"ORD-98765","item_name":"Blue Denim Jacket - Size M","customer_email":"customer@example.com","return_reason":"wrong_size","additional_details":"Fits too small, need size L","resolution_type":"exchange","exchange_pref":"Same item in size L","contact_method":"whatsapp","flow_token":"<TOKEN>"}" } } } } } Processing the Submission: // Parse the Flow submission const data = JSON.parse(payload.content.interactive.nfmReply.responseJson); // Validate order exists and is eligible for return const order = await validateOrder(data.order_number, data.customer_email); if (!order.exists) { await sendMessage(payload.user.msisdn, "We couldn't find that order. Please check your order number and try again."); return; } if (!order.eligibleForReturn) { await sendMessage(payload.user.msisdn, "This order is outside the 30-day return window. Please contact support for assistance."); return; } // Generate return authorization const returnAuth = await createReturnAuthorization({ orderId: order.id, itemName: data.item_name, reason: data.return_reason, additionalDetails: data.additional_details, resolutionType: data.resolution_type, exchangePreference: data.exchange_pref, customerEmail: data.customer_email }); // Generate and send return shipping label const shippingLabel = await generateShippingLabel({ returnAuthNumber: returnAuth.number, customerAddress: order.shippingAddress }); // Send confirmation with return label await sendMessage(payload.user.msisdn, { type: "document", document: { link: shippingLabel.url, filename: `Return_Label_${returnAuth.number}.pdf` }, caption: `Return authorized! Return #${returnAuth.number}

Print this label and attach it to your package. Drop it off at any shipping location.

You'll receive your ${data.resolution_type === 'refund' ? 'refund' : 'exchange'} within 5-7 business days after we receive your return.` }); // Log for analytics and quality tracking await logReturnRequest({ returnReason: data.return_reason, resolutionType: data.resolution_type, itemSku: order.itemSku, orderDate: order.createdAt }); Best Practices: Validate Immediately: Check order eligibility in real-time to prevent invalid returns Return Window: Enforce your return policy (e.g., 30 days from delivery) Fraud Prevention: Match email/phone to original order to prevent abuse Quality Insights: Track return reasons by product/SKU to identify quality issues Automation: Auto-approve simple returns (wrong size), flag complex ones (defective) for review Customer Experience: Send return label immediately, provide tracking updates
